package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;import java.nio.file.*;import java.util.*;
/** Keep game readiness and public update freshness visibly separate. */
public final class PublicationHealthScreen80 extends MaredScreen {
 private final Screen previous;private final java.util.function.Consumer<String> chosen;private String created="";private boolean delivered;private final PublicationHealthService80 service=new PublicationHealthService80();private String rootValue;private EditBox root;private final List<Button> buttons=new ArrayList<>();private int left,w,scroll,maxScroll;private long due;
 public PublicationHealthScreen80(Screen previous,String root,java.util.function.Consumer<String> chosen){super(tr("title"));this.previous=previous;rootValue=root;this.chosen=chosen;}
 private static Component tr(String key,Object...args){return Component.translatable("mared.publication80."+key,args);}
 private Button button(String key,int x,int y,int width,Runnable action){Button b=addRenderableWidget(Button.builder(tr(key),a->action.run()).bounds(x,y,width,20).build());buttons.add(b);return b;}
 @Override protected void init(){buttons.clear();w=Math.max(250,Math.min(680,width-24));left=(width-w)/2;root=addRenderableWidget(new EditBox(font,left,36,w-34,20,tr("root")));root.setMaxLength(4096);root.setValue(rootValue);button("browse",left+w-30,36,30,()->{collect();Path path;try{path=Path.of(rootValue);}catch(Exception bad){path=minecraft.gameDirectory.toPath();}minecraft.setScreen(new LocalPickerScreen68(this,true,path,p->{rootValue=p.toString();root.setValue(rootValue);}));});int bw=(w-8)/3;button("refresh",left,60,bw,this::refresh);button("new_release",left+bw+4,60,bw,()->{collect();minecraft.setScreen(new PublicationScreen79(this,rootValue));});button("https",left+2*(bw+4),60,bw,()->{collect();minecraft.setScreen(new HttpsScreen78(this,rootValue));});button("recovery",left,height-50,(w-4)/2,()->{collect();minecraft.setScreen(new RecoveryScreen77(this,rootValue,value->{created=value;rootValue=value;root.setValue(value);}));});button("reports",left+(w+4)/2,height-50,(w-4)/2,()->{collect();try{net.minecraft.Util.getPlatform().openFile(Path.of(rootValue).toFile());}catch(Exception ignored){}});button("back",left,height-26,w,this::onClose);if(!rootValue.isBlank())refresh();}
 private void collect(){if(root!=null)rootValue=root.getValue().trim();}
 private void refresh(){collect();if(!rootValue.isBlank())service.read(rootValue);due=System.nanoTime()+3_000_000_000L;}
 @Override public void tick(){root.setEditable(!service.busy());for(Button b:buttons)b.active=!service.busy();if(!service.busy()&&System.nanoTime()>due&&!root.getValue().isBlank())refresh();}
 @Override public void removed(){collect();}@Override public void onClose(){if(!service.busy()){collect();if(!delivered&&!created.isEmpty()){delivered=true;chosen.accept(created);}minecraft.setScreen(previous);}}@Override public boolean isPauseScreen(){return false;}
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*24)));return true;}
 private List<Component> lines(){var lines=new ArrayList<Component>();lines.add(tr("hint"));if(!root.getValue().trim().equals(service.observed())){lines.add(tr("select"));return lines;}if(service.result().equals("ERROR")){lines.add(tr("error"));return lines;}var d=service.data();if(d.isEmpty())return lines;String state=d.get("state");lines.add(tr("world",Component.translatable("mared.dedicated75.phase."+d.get("world")),d.get("generation")));lines.add(tr("state."+state));if(!d.get("release").equals("none"))lines.add(tr("release",d.get("release")));try{long expires=Long.parseLong(d.get("expires")),left=Long.parseLong(d.get("remainingMs"));if(expires>0){lines.add(tr("expires",java.time.Instant.ofEpochMilli(expires).toString()));lines.add(tr("remaining",left/60000));}}catch(Exception ignored){}if(!d.get("code").equals("NONE"))lines.add(Component.literal(d.get("code")));if(state.equals("BASELINE_EXPIRED"))lines.add(tr("expired_action"));if(state.equals("CLOCK_AHEAD"))lines.add(tr("clock_action"));if(state.equals("NOT_REPORTED"))lines.add(tr("old_owner"));lines.add(tr("historical"));return lines;}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,10,0xFFFFFFFF);var rows=new ArrayList<net.minecraft.util.FormattedCharSequence>();for(Component c:lines())rows.addAll(font.split(c,w-8));int top=88,bottom=Math.max(top,height-56),step=font.lineHeight+3;maxScroll=Math.max(0,rows.size()*step-(bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int y=top-scroll;for(var row:rows){if(y+step>=top&&y<bottom)g.drawString(font,row,left,y,0xFFCCD0DC,false);y+=step;}g.disableScissor();}super.render(g,mx,my,dt);}
}
